/**
 * Breakout candidates — 24 rows built from real generated series.
 *
 * Nothing here is invented: price, change, volume and RVOL are read off the
 * candle arrays, the breakout level is a real number pulled from the series that
 * matches the row's signal type, and every checklist item is an actual
 * comparison against the indicators.
 *
 * Scoring is a documented weighted blend, and the weights are chosen so the
 * ranking genuinely tracks its inputs — the rows with the strongest change and
 * relative volume sit near the top. A table that sorted by an invented score
 * would be lying to whoever reads it.
 */

import { getCompany } from "./companies.js"
import { generateCandles } from "./candles.js"
import { getIndicators } from "./indicators.js"
import { getSignalSummary } from "./signals.js"
import { getNews } from "./news.js"
import { coverage } from "./source.js"
import { ANCHOR_DATE } from "./companies.js"

export const BREAKOUT_SIGNALS = [
  "Resistance break",
  "New high",
  "VWAP break",
  "Premarket break",
]

/*
 * Fixed roster: 24 rows over 14 tickers, ten appearing twice and four once.
 * Hard-coded rather than drawn from the RNG so the table never reshuffles
 * between runs, and no ticker appears twice with the same signal.
 */
const ROSTER = [
  ["AAPL", "Resistance break"], ["AAPL", "VWAP break"],
  ["NVDA", "New high"], ["NVDA", "Resistance break"],
  ["MSFT", "Resistance break"],
  ["TSLA", "VWAP break"], ["TSLA", "Premarket break"],
  ["AMZN", "Resistance break"], ["AMZN", "New high"],
  ["PLTR", "New high"], ["PLTR", "Premarket break"],
  ["ACHR", "Premarket break"], ["ACHR", "VWAP break"],
  ["SOUN", "VWAP break"], ["SOUN", "Resistance break"],
  ["RKLB", "New high"], ["RKLB", "VWAP break"],
  ["IONQ", "Premarket break"], ["IONQ", "New high"],
  ["AVPT", "Resistance break"],
  ["MARA", "VWAP break"], ["MARA", "Premarket break"],
  ["LUNR", "Premarket break"],
  ["ASTS", "New high"],
]

const ANCHOR_UTC_OFFSET_HOURS = -4
const [A_Y, A_M, A_D] = ANCHOR_DATE.split("-").map(Number)
const ANCHOR_OPEN = Math.floor(
  Date.UTC(A_Y, A_M - 1, A_D, 0, 9 * 60 + 30 - ANCHOR_UTC_OFFSET_HOURS * 60, 0) / 1000
)
const ANCHOR_CLOSE = ANCHOR_OPEN + 390 * 60

function clamp01(x) {
  if (!Number.isFinite(x)) return 0
  return x < 0 ? 0 : x > 1 ? 1 : x
}

function round(value, digits = 2) {
  if (value === null || !Number.isFinite(value)) return null
  const f = Math.pow(10, digits)
  return Math.round(value * f) / f
}

/** Normalise a value into 0..1 against the observed spread of the whole set. */
function normalise(value, min, max) {
  if (!Number.isFinite(value) || max <= min) return 0.5
  return clamp01((value - min) / (max - min))
}

/** Highest high in candles[0 .. length-1-exclude]. */
function priorHigh(candles, exclude) {
  let high = -Infinity
  const end = Math.max(0, candles.length - exclude)
  for (let i = 0; i < end; i += 1) {
    if (candles[i].high > high) high = candles[i].high
  }
  return Number.isFinite(high) ? high : null
}

/**
 * The level the row claims to have broken.
 *
 * INVARIANT: a breakout level must sit BELOW the current price — it is a level
 * that has already been cleared. That rules out the naive readings: the 1Y high
 * is by definition at or above price, so using it directly would print "New
 * high" on a card whose price is under the level, which reads as a failed
 * breakout.
 *
 * So each signal names its natural level, and we fall through a list of real
 * levels from the series until one sits below price.
 */
function breakoutLevelFor(signal, ctx) {
  const { price, intraday, daily3m, yearly, sessionVwap } = ctx

  const prior = daily3m[daily3m.length - 2]
  const priorSessionHigh = prior ? prior.high : null

  // The session's opening-range high: the level an intraday breakout cleared.
  let openingHigh = -Infinity
  for (let i = 0; i < Math.min(30, intraday.length); i += 1) {
    if (intraday[i].high > openingHigh) openingHigh = intraday[i].high
  }
  if (!Number.isFinite(openingHigh)) openingHigh = null

  // "New high" means the previous peak, excluding the recent run that cleared it.
  const yearPriorHigh = priorHigh(yearly, 10)
  const quarterPriorHigh = priorHigh(daily3m, 5)

  const candidates = {
    "New high": [yearPriorHigh, quarterPriorHigh, priorSessionHigh, openingHigh],
    "VWAP break": [sessionVwap, openingHigh, priorSessionHigh],
    "Premarket break": [priorSessionHigh, openingHigh, quarterPriorHigh],
    "Resistance break": [quarterPriorHigh, priorSessionHigh, openingHigh],
  }

  const list = candidates[signal] || candidates["Resistance break"]
  for (const level of list) {
    if (level !== null && Number.isFinite(level) && level < price) return round(level)
  }
  // Nothing in the series sits below price — fall back to a level just under it.
  return round(price * 0.985)
}

function buildRow(symbol, signal, index) {
  const company = getCompany(symbol)
  if (!company) return null

  const intraday = generateCandles(symbol, "1D")
  const daily3m = generateCandles(symbol, "3M")
  const yearly = generateCandles(symbol, "1Y")
  if (!intraday.length || !daily3m.length) return null

  const ind = getIndicators(symbol, "1D")
  const summary = getSignalSummary(symbol, "1D")

  /*
   * Session figures must come from ONE series.
   *
   * When real daily data is present the intraday series is still synthetic, so
   * dividing a synthetic session volume by a real 3-month mean compared two
   * different universes and produced a meaningless RVOL — which is exactly what
   * broke the score/RVOL correlation. With real data we read the session off the
   * last real daily bar and measure RVOL against the bars before it.
   */
  const useRealSession = coverage(symbol, "3M").real && daily3m.length >= 2
  const lastDaily = daily3m[daily3m.length - 1]

  const sessionOpen = useRealSession ? lastDaily.open : intraday[0].open
  const price = useRealSession ? lastDaily.close : ind.latest.close
  const changePct = sessionOpen > 0 ? ((price - sessionOpen) / sessionOpen) * 100 : 0

  let volume = 0
  if (useRealSession) {
    volume = lastDaily.volume
  } else {
    for (const c of intraday) volume += c.volume
  }

  // RVOL: the session against the average of the sessions before it, both from
  // the same series.
  let priorTotal = 0
  const priorBars = useRealSession ? daily3m.slice(0, -1) : daily3m
  for (const c of priorBars) priorTotal += c.volume
  const avgDaily = priorBars.length ? priorTotal / priorBars.length : 0
  const rvol = avgDaily > 0 ? volume / avgDaily : null

  const sessionVwap = ind.latest.vwap
  const level = breakoutLevelFor(signal, {
    price,
    intraday,
    daily3m,
    yearly,
    sessionVwap,
  })

  // News published inside the anchor session.
  const newsToday = getNews(symbol).filter(
    n => n.timestamp >= ANCHOR_OPEN && n.timestamp <= ANCHOR_CLOSE
  ).length

  /*
   * The price path the card draws, and the bar where price last crossed the
   * level from below. `detectedAt` is that bar's real timestamp — not a
   * decorative "2 hours ago" — so the card's chart, its distance figure and its
   * detection time all describe the same event.
   */
  const SERIES_POINTS = 64
  // Draw the same series the row's numbers came from, or the card's chart would
  // show synthetic intraday wiggles under a real daily price.
  const chartBars = useRealSession ? daily3m : intraday
  const series = []
  for (let i = 0; i < SERIES_POINTS; i += 1) {
    const idx = Math.round((i * (chartBars.length - 1)) / (SERIES_POINTS - 1))
    series.push(chartBars[idx].close)
  }

  let crossedAt = null
  for (let i = chartBars.length - 1; i > 0; i -= 1) {
    if (level !== null && chartBars[i - 1].close <= level && chartBars[i].close > level) {
      crossedAt = chartBars[i].time
      break
    }
  }

  // Distance price has travelled beyond the level it cleared.
  const distancePct =
    level !== null && level > 0 ? ((price - level) / level) * 100 : null

  const priorDaily = daily3m[daily3m.length - 2]
  const checklist = [
    { label: "Above VWAP", passed: Boolean(sessionVwap !== null && price > sessionVwap) },
    { label: "Volume above 2x average", passed: Boolean(rvol !== null && rvol > 2) },
    { label: "RSI above 50", passed: Boolean(ind.latest.rsi14 !== null && ind.latest.rsi14 > 50) },
    { label: "EMA 9 above EMA 20", passed: Boolean(ind.latest.ema9 !== null && ind.latest.ema20 !== null && ind.latest.ema9 > ind.latest.ema20) },
    { label: "Closed above breakout level", passed: Boolean(level !== null && price > level) },
    { label: "Above prior session high", passed: Boolean(priorDaily && price > priorDaily.high) },
  ]

  // Technical: how many of the six signals read bullish.
  const technical = Math.round((summary.bullish / (summary.total || 6)) * 100)

  // Fundamental: net margin and revenue growth, both bounded into 0..100.
  // Loss-making names score low here, which is the honest answer.
  const marginScore = clamp01(((company.netMargin === null ? -0.5 : company.netMargin) + 0.3) / 0.8)
  const growthScore = clamp01(((company.revenueGrowthYoY === null ? 0 : company.revenueGrowthYoY) + 0.1) / 0.8)
  const fundamental = Math.round((marginScore * 0.55 + growthScore * 0.45) * 100)

  const news = Math.round(clamp01(newsToday / 2) * 100)

  return {
    id: `${symbol.toLowerCase()}-${index + 1}`,
    symbol,
    name: company.name,
    brandColor: company.brandColor,
    price: round(price),
    changePct: round(changePct),
    volume,
    rvol: round(rvol),
    breakoutLevel: level,
    distancePct: round(distancePct),
    series,
    detectedAt: crossedAt,
    sessionOpen: round(sessionOpen),
    signal,
    checklist,
    // Raw inputs kept for the second pass, which needs the whole set to normalise.
    _technical: technical,
    _fundamental: fundamental,
    _news: news,
  }
}

/*
 * Score weights. Momentum carries the most so the ranking tracks the change and
 * relative-volume columns a reader can see; technical is next; fundamentals and
 * news are context rather than drivers on a one-day breakout screen.
 */
const WEIGHTS = { technical: 0.3, momentum: 0.4, fundamental: 0.15, news: 0.15 }

function build() {
  const rows = ROSTER.map(([symbol, signal], i) => buildRow(symbol, signal, i)).filter(Boolean)

  // Second pass: momentum is normalised against the observed spread of the set,
  // so the scale actually spreads out instead of bunching in the middle.
  const changes = rows.map(r => r.changePct).filter(Number.isFinite)
  const rvols = rows.map(r => r.rvol).filter(Number.isFinite)
  const minC = Math.min(...changes)
  const maxC = Math.max(...changes)
  const minV = Math.min(...rvols)
  const maxV = Math.max(...rvols)

  const scored = rows.map(row => {
    const changeScore = normalise(row.changePct, minC, maxC)
    const rvolScore = normalise(row.rvol, minV, maxV)
    const momentum = Math.round((changeScore * 0.6 + rvolScore * 0.4) * 100)

    const score = Math.round(
      row._technical * WEIGHTS.technical +
        momentum * WEIGHTS.momentum +
        row._fundamental * WEIGHTS.fundamental +
        row._news * WEIGHTS.news
    )

    const { _technical, _fundamental, _news, ...rest } = row
    return {
      ...rest,
      score,
      subScores: {
        technical: _technical,
        fundamental: _fundamental,
        momentum,
        news: _news,
      },
    }
  })

  // Sorted by score, with a stable id tie-break.
  return scored.sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
}

export const BREAKOUTS = build()

export function getBreakouts() {
  return BREAKOUTS
}
